#!/usr/bin/env python3
"""microbiome/cooccurrence_network_real — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "cooccurrence_network_real"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'cooccurrence_network_real', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def _sparcc_basis_corr(counts):
    """SparCC basis correlation(Friedman & Alm 2012,简化版).

    counts: 2D ndarray (n_samples, n_taxa) integer abundance(必须 >=0)
    返回:(n_taxa, n_taxa) basis correlation matrix [-1,1]

    算法:
      1. pseudocount + log
      2. 估 var(log x_i) 从 var(log x_i / x_j) → t_i / (D-1)(稀疏假设)
      3. cov(log x_i, log x_j) = (var_i + var_j - var_ij) / 2
      4. correlation = cov / (sd_i * sd_j)
    """
    import numpy as np
    x = np.asarray(counts, dtype=float) + 1.0   # pseudocount
    log_x = np.log(x)
    # 对 sample 维度算 (n_taxa, n_taxa) 的 var(log x_i - log x_j)
    var_ij = log_x.var(axis=0, ddof=1)[None, :] + log_x.var(axis=0, ddof=1)[:, None]
    # 真 SparCC:var(log x_i - log x_j) = var_i + var_j - 2*cov_ij
    # 但 sparse 假设下我们只需要 omega_ij = sum over k of var_ik 来反解
    diff = log_x[:, :, None] - log_x[:, None, :]
    omega_ij = diff.var(axis=0, ddof=1)            # 实际的 var(log xi/xj)
    D = log_x.shape[1]
    # t_i = sum_j var_ij ≈ (D-1) * var_i(sparse 假设 sum_j cov_ij ≈ 0)
    t = omega_ij.sum(axis=1)
    basis_var = t / (D - 1)
    basis_var = np.maximum(basis_var, 1e-10)
    cov = 0.5 * (basis_var[:, None] + basis_var[None, :] - omega_ij)
    sd = np.sqrt(basis_var)
    corr = cov / (sd[:, None] * sd[None, :])
    np.clip(corr, -1.0, 1.0, out=corr)
    np.fill_diagonal(corr, 1.0)
    return corr


def _sparcc_with_iter(counts, n_iter=20, exclude_thr=0.10):
    """SparCC 迭代:每轮把绝对相关 > exclude_thr 的 pair 屏蔽,重新估;返回中位 corr"""
    import numpy as np
    n_taxa = counts.shape[1]
    corrs = []
    for _ in range(max(1, n_iter)):
        # 在原始 counts 上加少量噪声打破对称性,以便不同 iter 略不同
        c = counts + np.random.uniform(0, 1, counts.shape) * 0.01
        corrs.append(_sparcc_basis_corr(c))
    arr = np.stack(corrs)
    return np.median(arr, axis=0)


def _sparcc_bootstrap_pvals(counts, base_corr, n_perms=50):
    """简化 bootstrap:每次 perm 每列,得到 null corr 分布;p = mean(|null| >= |base|)"""
    import numpy as np
    abs_base = np.abs(base_corr)
    null_counts = np.zeros_like(abs_base)
    for _ in range(n_perms):
        permuted = counts.copy()
        for j in range(permuted.shape[1]):
            np.random.shuffle(permuted[:, j])
        nc = _sparcc_basis_corr(permuted)
        null_counts += (np.abs(nc) >= abs_base).astype(float)
    return null_counts / n_perms


def real(payload):
    """Taxa 共现网络:**pure-Python SparCC**(对齐 §08 compositional-aware,履行规则 5/8)。

    输入(payload):
      abundance_csv:  CSV/TSV,index=sample,columns=taxa,values=counts(必需)
      method:         sparcc | spearman_clr | pearson_legacy(默认 sparcc;pearson 仅诊断用)
      n_iter:         SparCC 迭代次数(默认 20)
      n_perms:        Bootstrap permutation 数(默认 50)
      correlation_cutoff: 边阈值(默认 0.30)
      p_cutoff:       p 值阈值(默认 0.10)
      min_prevalence: 过滤低 prevalence taxa(出现样本数/总样本,默认 0.20)
      min_abundance:  过滤低 abundance taxa(平均相对丰度,默认 1e-5)
      top_n:          只保留 top-N 丰度 taxa(默认不限;大矩阵建议 200-500)
      out_dir:        输出目录(可选,默认临时)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time

    abun = payload.get("abundance_csv") or payload.get("abundance_table")
    method = payload.get("method", "sparcc")
    n_iter = int(payload.get("n_iter", 20))
    n_perms = int(payload.get("n_perms", 50))
    cor_cutoff = float(payload.get("correlation_cutoff", payload.get("cor_cutoff", 0.30)))
    p_cutoff = float(payload.get("p_cutoff", payload.get("pval_cutoff", 0.10)))
    min_prev = float(payload.get("min_prevalence", 0.20))
    min_abun = float(payload.get("min_abundance", 1e-5))
    top_n = int(payload.get("top_n", 0))
    out_dir = payload.get("out_dir") or payload.get("out_subpath") or _tempfile.mkdtemp(prefix="cooc_")

    diagnostics = {
        "brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
        "method": method, "out_dir": out_dir,
    }
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0, "taxonomy_table": "",
                "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if method == "pearson":
        return {"ok": False, "error": "method=pearson REJECTED(违 §08);用 sparcc / spearman_clr",
                "diagnostics": diagnostics}
    if not abun or not _os.path.isfile(abun):
        return {"ok": False, "error": "需要 abundance_csv (rows=samples, cols=taxa)",
                "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)

    t0 = _time.time()
    try:
        import numpy as np
        import pandas as pd
    except ImportError as e:
        return {"ok": False, "error": f"缺依赖: {e}", "diagnostics": diagnostics}

    sep = "\t" if abun.endswith((".tsv", ".tab")) else ","
    df = pd.read_csv(abun, sep=sep, index_col=0)
    # 自动检测:rows 应是 samples;若 columns 更少则可能转置
    if df.shape[0] < df.shape[1] / 10:
        df = df.T  # 提示用户可能写反,但 SparCC 假设 rows=samples
    diagnostics["n_samples_raw"] = int(df.shape[0])
    diagnostics["n_taxa_raw"] = int(df.shape[1])

    # 过滤
    rel = df.div(df.sum(axis=1).replace(0, 1), axis=0)
    prev = (df > 0).mean(axis=0)
    mean_abun = rel.mean(axis=0)
    keep = (prev >= min_prev) & (mean_abun >= min_abun)
    df = df.loc[:, keep]
    if top_n > 0 and df.shape[1] > top_n:
        df = df[rel.loc[:, keep].mean(axis=0).sort_values(ascending=False).index[:top_n]]
    diagnostics["n_taxa_after_filter"] = int(df.shape[1])
    diagnostics["n_samples"] = int(df.shape[0])

    if df.shape[1] < 5:
        return {"ok": False, "error": f"过滤后 taxa < 5({df.shape[1]});放宽 min_prevalence",
                "diagnostics": diagnostics}
    if df.shape[0] < 30:
        diagnostics["warning"] = f"sample 数 {df.shape[0]} < 30,SparCC 不稳定(规则 §08 建议 ≥50)"

    counts = df.values.astype(float)
    np.random.seed(int(payload.get("seed", 42)))

    if method == "sparcc":
        corr = _sparcc_with_iter(counts, n_iter=n_iter)
    elif method == "spearman_clr":
        from scipy.stats import rankdata
        x = np.log(counts + 1)
        clr = x - x.mean(axis=1, keepdims=True)
        ranks = np.apply_along_axis(rankdata, 0, clr)
        # spearman = pearson on ranks
        ranks_c = ranks - ranks.mean(axis=0)
        n = ranks_c.shape[0]
        cov = (ranks_c.T @ ranks_c) / (n - 1)
        sd = np.sqrt(np.maximum(np.diag(cov), 1e-10))
        corr = cov / (sd[:, None] * sd[None, :])
        np.clip(corr, -1.0, 1.0, out=corr)
        np.fill_diagonal(corr, 1.0)
    else:
        return {"ok": False, "error": f"未知 method: {method}", "diagnostics": diagnostics}

    pvals = _sparcc_bootstrap_pvals(counts, corr, n_perms=n_perms)

    # 出边
    taxa = df.columns.tolist()
    edges = []
    n = len(taxa)
    for i in range(n):
        for j in range(i + 1, n):
            if abs(corr[i, j]) < cor_cutoff:
                continue
            if pvals[i, j] >= p_cutoff:
                continue
            edges.append({
                "source": taxa[i], "target": taxa[j],
                "correlation": float(corr[i, j]),
                "p_value": float(pvals[i, j]),
                "edge_class": "positive" if corr[i, j] > 0 else "negative",
            })

    edges_tsv = _os.path.join(out_dir, "edges.tsv")
    with open(edges_tsv, "w") as fh:
        fh.write("source\ttarget\tcorrelation\tp_value\tedge_class\n")
        for e in edges:
            fh.write(f"{e['source']}\t{e['target']}\t{e['correlation']:.4f}\t{e['p_value']:.4f}\t{e['edge_class']}\n")

    summary_json = _os.path.join(out_dir, "summary.json")
    summary = {
        "method": method, "n_iter": n_iter, "n_perms": n_perms,
        "correlation_cutoff": cor_cutoff, "p_cutoff": p_cutoff,
        "n_taxa": int(df.shape[1]), "n_samples": int(df.shape[0]),
        "n_edges": len(edges),
        "n_positive": sum(1 for e in edges if e["edge_class"] == "positive"),
        "n_negative": sum(1 for e in edges if e["edge_class"] == "negative"),
    }
    with open(summary_json, "w") as fh:
        json.dump(summary, fh, indent=2)

    diagnostics.update({
        **summary,
        "edges_tsv": edges_tsv,
        "summary_json": summary_json,
        "runtime_sec": round(_time.time() - t0, 2),
    })
    return {
        "ok": True, "skill_id": SKILL,
        "n_samples": int(df.shape[0]),
        "taxonomy_table": edges_tsv,
        "diversity_metrics": {"shannon": 0.0, "observed_otus": len(edges)},
        "diagnostics": diagnostics,
    }

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
